contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address logAddr, uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(amt > 0);
        require(address(this).balance >= amt);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        c.Deposit{value: amt}(); if (__ESBMC_reverted()) return;

        c.Collect(amt); if (__ESBMC_reverted()) return;

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterEth = address(c).balance;

        assert(afterBal == beforeBal && afterEth == beforeEth);
    }
    receive() external payable {}
}

